<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/ocr_auth.php'; apply_security_headers(); start_app_session(); $user=ocr_read_token($_COOKIE['access_token']??null);if(!$user){header('Location: ../../frontend/login.php');exit;}
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: ../../frontend/perfil.php');exit;} ocr_require_post_csrf();
$id=filter_input(INPUT_POST,'id_proveedor',FILTER_VALIDATE_INT)?:0;$name=isset($_POST['nombre_empresa'])&&is_string($_POST['nombre_empresa'])?trim(mb_substr($_POST['nombre_empresa'],0,150,'UTF-8')):'';$rtn=preg_replace('/\D/','',isset($_POST['rtn'])&&is_string($_POST['rtn'])?$_POST['rtn']:'');$category=filter_input(INPUT_POST,'id_categoria',FILTER_VALIDATE_INT)?:0;$phone=preg_replace('/\D/','',isset($_POST['telefono'])&&is_string($_POST['telefono'])?$_POST['telefono']:'');$email=isset($_POST['correo'])&&is_string($_POST['correo'])?trim(mb_substr($_POST['correo'],0,120,'UTF-8')):'';$address=isset($_POST['direccion'])&&is_string($_POST['direccion'])?trim(mb_substr($_POST['direccion'],0,255,'UTF-8')):'';
$fail=static function(string $m,int $id):void{$_SESSION['proveedor_flash']=$m;header('Location: ../../frontend/editar_proveedor.php?id='.$id);exit;};
if($id<1||$name===''||$category<1)$fail('Completa el nombre y la categoría.',$id);if($rtn!==''&&strlen($rtn)!==14)$fail('El RTN debe tener 14 dígitos.',$id);if($phone!==''&&!preg_match('/^[23789][0-9]{7}$/',$phone))$fail('El teléfono debe tener 8 dígitos hondureños.',$id);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$fail('El correo no tiene formato válido.',$id);
try{$pdo=database();$owner=$pdo->prepare('SELECT id_proveedor,rtn,nombre_empresa,id_categoria,direccion,correo FROM proveedor WHERE id_proveedor=:id AND dni_usuario_registro=:dni LIMIT 1');$owner->execute(['id'=>$id,'dni'=>$user['sub']]);$old=$owner->fetch();if(!$old)$fail('No puedes editar este proveedor.',$id);$catCheck=$pdo->prepare('SELECT 1 FROM categoria WHERE id_categoria=:id');$catCheck->execute(['id'=>$category]);if(!$catCheck->fetchColumn())$fail('La categoría ya no está disponible.',$id);if($rtn!==''){$duplicate=$pdo->prepare('SELECT 1 FROM proveedor WHERE rtn=:rtn AND id_proveedor<>:id');$duplicate->execute(['rtn'=>$rtn,'id'=>$id]);if($duplicate->fetchColumn())$fail('Ese RTN ya pertenece a otro proveedor.',$id);}
$pdo->beginTransaction();$update=$pdo->prepare('UPDATE proveedor SET nombre_empresa=:name,rtn=:rtn,id_categoria=:cat,direccion=:address,correo=:email WHERE id_proveedor=:id AND dni_usuario_registro=:dni');$update->execute(['name'=>$name,'rtn'=>$rtn?:null,'cat'=>$category,'address'=>$address?:null,'email'=>$email?:null,'id'=>$id,'dni'=>$user['sub']]);if($phone!==''){$save=$pdo->prepare("INSERT INTO proveedor_telefono (id_proveedor,numero,tipo,origen_dato) VALUES (:id,:phone,:type,'manual') ON DUPLICATE KEY UPDATE tipo=VALUES(tipo)");$save->execute(['id'=>$id,'phone'=>$phone,'type'=>str_starts_with($phone,'2')?'telefono':'celular']);}$pdo->commit();$_SESSION['proveedor_flash']='Los datos del proveedor se actualizaron.';header('Location: ../../frontend/perfil.php');exit;
}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());$fail('No se pudieron guardar los cambios. Revisa los datos e inténtalo otra vez.',$id);}
